-- ==============================================================
-- FOXSA NEWS - SUPABASE COMPLETE DATABASE SCHEMA
-- Jalankan seluruh script ini di Supabase SQL Editor (Dashboard > SQL Editor)
-- Seluruh data Berita, Akun Staff, Former Staff, dan Chat Redaksi akan tersimpan di Supabase!
-- ==============================================================

-- 1. TABEL BERITA & ARTIKEL (foxsa_posts)
CREATE TABLE IF NOT EXISTS public.foxsa_posts (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  published TIMESTAMPTZ DEFAULT now(),
  updated TIMESTAMPTZ DEFAULT now(),
  author TEXT NOT NULL,
  author_avatar TEXT DEFAULT '',
  author_bio TEXT DEFAULT '',
  labels JSONB DEFAULT '[]'::jsonb,
  featured_image TEXT DEFAULT '',
  snippet TEXT DEFAULT '',
  content TEXT NOT NULL,
  original_url TEXT DEFAULT '',
  popular BOOLEAN DEFAULT false,
  comments JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. TABEL AKUN STAFF & JURNALIS (foxsa_staff_accounts)
CREATE TABLE IF NOT EXISTS public.foxsa_staff_accounts (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  username TEXT UNIQUE NOT NULL,
  password TEXT NOT NULL,
  display_name TEXT NOT NULL,
  author_name TEXT,
  role TEXT NOT NULL DEFAULT 'Junior Reporter',
  status TEXT NOT NULL DEFAULT 'approved', -- 'approved', 'pending', 'rejected', 'retired'
  is_admin BOOLEAN NOT NULL DEFAULT false,
  is_former BOOLEAN NOT NULL DEFAULT false,
  avatar TEXT,
  quote TEXT DEFAULT '',
  bio TEXT DEFAULT '',
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- 3. TABEL FORMER STAFF / ALUMNI (foxsa_former_staff)
CREATE TABLE IF NOT EXISTS public.foxsa_former_staff (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  former_role TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'staff', -- 'leadership', 'management', 'staff'
  badge TEXT,
  period TEXT NOT NULL,
  avatar TEXT,
  bio TEXT DEFAULT '',
  legacy TEXT DEFAULT '',
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 4. TABEL CHAT REDAKSI / ADMIN CHAT (foxsa_admin_chats)
CREATE TABLE IF NOT EXISTS public.foxsa_admin_chats (
  id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
  sender_username TEXT NOT NULL,
  sender_name TEXT NOT NULL,
  sender_role TEXT,
  sender_avatar TEXT,
  message TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- 5. ROW LEVEL SECURITY (RLS) & PUBLIC ACCESS
ALTER TABLE public.foxsa_posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.foxsa_staff_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.foxsa_former_staff ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.foxsa_admin_chats ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public access for foxsa_posts" ON public.foxsa_posts;
CREATE POLICY "Public access for foxsa_posts" ON public.foxsa_posts FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public access for foxsa_staff_accounts" ON public.foxsa_staff_accounts;
CREATE POLICY "Public access for foxsa_staff_accounts" ON public.foxsa_staff_accounts FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public access for foxsa_former_staff" ON public.foxsa_former_staff;
CREATE POLICY "Public access for foxsa_former_staff" ON public.foxsa_former_staff FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public access for foxsa_admin_chats" ON public.foxsa_admin_chats;
CREATE POLICY "Public access for foxsa_admin_chats" ON public.foxsa_admin_chats FOR ALL USING (true) WITH CHECK (true);

-- BERIKAN HAK AKSES LENGKAP KE ANON & AUTHENTICATED
GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT ALL ON TABLE public.foxsa_posts TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.foxsa_staff_accounts TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.foxsa_former_staff TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.foxsa_admin_chats TO anon, authenticated, service_role;

-- 6. REALTIME REPLICATION (Agar chat, berita, dan akun langsung live real-time)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'foxsa_posts') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.foxsa_posts;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'foxsa_admin_chats') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.foxsa_admin_chats;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'foxsa_staff_accounts') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.foxsa_staff_accounts;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'foxsa_former_staff') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.foxsa_former_staff;
  END IF;
EXCEPTION WHEN OTHERS THEN
  NULL;
END $$;

-- 7. SEED DATA AWAL BERITA (7 ARTIKEL ROLEPLAY RESMI FOXSA NEWS)
INSERT INTO public.foxsa_posts (id, slug, title, published, updated, author, author_avatar, author_bio, labels, featured_image, snippet, content, original_url, popular, comments)
VALUES
  ('8409961441289867617', 'dua-tersangka-diamankan-usai-kejar', 'Dua Tersangka Diamankan Usai Kejar-kejaran dengan Polisi di Flint County', '2026-06-10T09:04:21.098-07:00', '2026-06-10T09:04:21.098-07:00', 'Bryan Andregaz', 'https://4.bp.blogspot.com/-uCjYgVFIh70/VuOLn-mL7PI/AAAAAAAADUs/Kcu9wJbv790hIo83rI_s7lLW3zkLY01EA/s100/avatar.png', 'FoxSA News Journalist & Field Reporter', '["Crime","Government & Emergency Services","LSPD"]'::jsonb, 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjlKv2unDHTKu1yaEwD74IuZ6Rihb9Gp_2WHHbiuR5LTPDWDDOM0sN4g1VjW8wlEJEyxBpRSGtQ4NHyrtb48hyCPYKfr0JJl3p6k14OFPZ7Livr4XYqprbkaJxcWtHQlxJZ_UgDSq7XI5x0U1ULRx-IhnqI4d0f-4anC_S8rJwqSG2vLXIWzDJs0EbFP9E/s1200/file_00000000fba47206846a8a316bd34bb5.png', 'Picture : Gavin Andregaz Flint County, 10 Juni 2026, pukul 22.40 — Sebuah aksi pengejaran kendaraan yang melibatkan aparat kepolisian berakh...', '<p></p><div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjlKv2unDHTKu1yaEwD74IuZ6Rihb9Gp_2WHHbiuR5LTPDWDDOM0sN4g1VjW8wlEJEyxBpRSGtQ4NHyrtb48hyCPYKfr0JJl3p6k14OFPZ7Livr4XYqprbkaJxcWtHQlxJZ_UgDSq7XI5x0U1ULRx-IhnqI4d0f-4anC_S8rJwqSG2vLXIWzDJs0EbFP9E/s1448/file_00000000fba47206846a8a316bd34bb5.png" imageanchor="1" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="1086" data-original-width="1448" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjlKv2unDHTKu1yaEwD74IuZ6Rihb9Gp_2WHHbiuR5LTPDWDDOM0sN4g1VjW8wlEJEyxBpRSGtQ4NHyrtb48hyCPYKfr0JJl3p6k14OFPZ7Livr4XYqprbkaJxcWtHQlxJZ_UgDSq7XI5x0U1ULRx-IhnqI4d0f-4anC_S8rJwqSG2vLXIWzDJs0EbFP9E/s1200/file_00000000fba47206846a8a316bd34bb5.png" /></a></div><div class="separator" style="clear: both; text-align: center;"><i>Picture : Gavin Andregaz</i>&nbsp;</div><p></p><p style="text-align: justify;">Flint County, 10 Juni 2026, pukul 22.40 — Sebuah aksi pengejaran kendaraan yang melibatkan aparat kepolisian berakhir di wilayah Flint County pada Rabu malam. Insiden tersebut terjadi setelah petugas berupaya menghentikan sebuah kendaraan jenis Sultan untuk pemeriksaan, namun pengemudi memilih melarikan diri.</p><p style="text-align: justify;">Berdasarkan keterangan yang disampaikan oleh Deputy Cornelli kepada FOXSA News, kendaraan tersebut tidak mematuhi perintah berhenti dari petugas dan justru memacu kendaraan, sehingga memicu pengejaran yang berlangsung di sejumlah ruas jalan wilayah Flint County.</p><div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgAO6z_HfVuAKA6av1RQAWwJZnIXVuCLrR2Flq7XYwrNj2bXivTF2FRv22fl4y0VWc5-NOdIdqng5nRPbfDM9JuupO0rdSvGsUlDiWhVHoJ6YI5yizDjmcNU8sdVlu5J2F8TpNuSGN6yeMFDyuAy1kY6qzF4DN1BRTeJ18oQ-5A0ag9PcdZyN93E3FatdI/s1448/file_00000000bfa47208900e1fc5d3596b03.png" imageanchor="1" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="1086" data-original-width="1448" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgAO6z_HfVuAKA6av1RQAWwJZnIXVuCLrR2Flq7XYwrNj2bXivTF2FRv22fl4y0VWc5-NOdIdqng5nRPbfDM9JuupO0rdSvGsUlDiWhVHoJ6YI5yizDjmcNU8sdVlu5J2F8TpNuSGN6yeMFDyuAy1kY6qzF4DN1BRTeJ18oQ-5A0ag9PcdZyN93E3FatdI/s1200/file_00000000bfa47208900e1fc5d3596b03.png" /></a></div><p style="text-align: center;"><i>Picture : Gavin Andregaz</i></p><p style="text-align: justify;">Pengejaran berakhir ketika kendaraan yang dikendarai dua tersangka kehilangan kendali dan menabrak sebuah tiang di tepi jalan. Benturan keras tersebut menyebabkan kedua tersangka mengalami luka-luka dan membutuhkan penanganan medis segera.</p><p style="text-align: justify;">Setelah situasi berhasil diamankan oleh petugas kepolisian, tim medis tiba di lokasi untuk memberikan pertolongan pertama kepada kedua tersangka sebelum mereka menjalani proses penanganan lebih lanjut.</p><p style="text-align: justify;">Deputy Cornelli menjelaskan bahwa kedua tersangka berhasil diamankan setelah kecelakaan tersebut. Hingga berita ini diturunkan, pihak kepolisian masih melakukan penyelidikan guna mengetahui motif pelarian serta dugaan pelanggaran yang melatarbelakangi upaya penghentian kendaraan tersebut.</p><p style="text-align: justify;">Tidak ada laporan korban jiwa dalam kejadian ini. Aparat mengimbau masyarakat untuk selalu mematuhi perintah petugas dan peraturan lalu lintas guna menjaga keselamatan bersama.</p><p><br /></p><p>FOXSA News | Flint County</p>', 'https://foxsanews.blogspot.com/2026/06/dua-tersangka-diamankan-usai-kejar.html', true, '[]'::jsonb),
  ('2661902724525992618', 'lsfd-academy-class-426-san-fierro', 'LSFD Academy Class 4/26 - San Fierro', '2026-06-02T17:46:13.923-07:00', '2026-06-02T17:50:21.615-07:00', 'Bryan Andregaz', 'https://4.bp.blogspot.com/-uCjYgVFIh70/VuOLn-mL7PI/AAAAAAAADUs/Kcu9wJbv790hIo83rI_s7lLW3zkLY01EA/s100/avatar.png', 'FoxSA News Journalist & Field Reporter', '["Government & Emergency Services"]'::jsonb, 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgefFBBjMEeXEyU2XtAK_OsPzy8w0D8gdHiRu4PJhvV4iLnFfbRNHRYuqpr_AVBDDZt4Ez85x-VC5eXxIjb8pOUJCZHhAbCoKe3Y-1fLj0FlKZLWtoHm4BP9_7wyt7a_Ac1YDlnFRl-MQ6v2ePiAu9flb1ZSo0eQIpodsFOQlvQb-HUlQN4FJe59bX6lF0/s1200/IMG-20260531-WA0019.jpg', 'San Fierro, 31 Mei 2026 — Suasana penuh kebanggaan dan semangat mewarnai Lapangan Kota San Fierro saat Los Santos Fire Department (LSFD) Cla...', '<p></p><div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgefFBBjMEeXEyU2XtAK_OsPzy8w0D8gdHiRu4PJhvV4iLnFfbRNHRYuqpr_AVBDDZt4Ez85x-VC5eXxIjb8pOUJCZHhAbCoKe3Y-1fLj0FlKZLWtoHm4BP9_7wyt7a_Ac1YDlnFRl-MQ6v2ePiAu9flb1ZSo0eQIpodsFOQlvQb-HUlQN4FJe59bX6lF0/s1125/IMG-20260531-WA0019.jpg" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="580" data-original-width="1125" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgefFBBjMEeXEyU2XtAK_OsPzy8w0D8gdHiRu4PJhvV4iLnFfbRNHRYuqpr_AVBDDZt4Ez85x-VC5eXxIjb8pOUJCZHhAbCoKe3Y-1fLj0FlKZLWtoHm4BP9_7wyt7a_Ac1YDlnFRl-MQ6v2ePiAu9flb1ZSo0eQIpodsFOQlvQb-HUlQN4FJe59bX6lF0/s1200/IMG-20260531-WA0019.jpg" /></a></div><p style="text-align: justify;">San Fierro, 31 Mei 2026 — Suasana penuh kebanggaan dan semangat mewarnai Lapangan Kota San Fierro saat Los Santos Fire Department (LSFD) Class 4/26 melaksanakan prosesi kelulusan setelah menyelesaikan seluruh rangkaian pendidikan dan pelatihan akademi.</p><p style="text-align: justify;">Acara tersebut menjadi penanda berakhirnya masa pembinaan para peserta yang selama beberapa waktu terakhir menjalani berbagai pelatihan, mulai dari kedisiplinan, kesiapsiagaan, hingga penanganan situasi darurat. Seluruh peserta menunjukkan dedikasi dan kerja keras sepanjang masa akademi hingga berhasil mencapai tahap kelulusan.</p><p style="text-align: justify;">Prosesi berlangsung tertib dan penuh kebanggaan, serta dihadiri oleh jajaran LSFD, awak media, dan masyarakat yang turut menyaksikan momen penting tersebut. Sejumlah unit pemadam kebakaran tampak berjajar di sekitar lokasi acara sebagai simbol kebanggaan institusi terhadap para lulusan baru.</p><p style="text-align: justify;">Dalam sambutannya, pihak LSFD menyampaikan apresiasi kepada seluruh peserta yang telah menyelesaikan masa akademi dengan penuh komitmen dan disiplin. Kelulusan ini menjadi salah satu momen penting dalam perjalanan para anggota baru sebelum memasuki tahapan tugas dan tanggung jawab berikutnya.</p><p style="text-align: justify;">Kehadiran keluarga, masyarakat, serta media yang meliput kegiatan tersebut turut menambah kemeriahan acara. Momen ini menjadi bukti bahwa profesi pemadam kebakaran memiliki peran penting dalam menjaga keselamatan dan memberikan pelayanan darurat bagi masyarakat.</p><p style="text-align: justify;">Dengan berakhirnya akademi Class 4/26, para lulusan kini menutup satu babak penting dalam perjalanan mereka di LSFD dan membawa pengalaman berharga yang telah diperoleh selama masa pelatihan.</p><p style="text-align: justify;"><br /></p><p style="text-align: justify;">Reporter: Bryan Andregaz</p><p style="text-align: justify;">Tanggal: 31 Mei 2026</p><p style="text-align: justify;">FOXSA NEWS | Serving The Truth, Delivering The News</p>', 'https://foxsanews.blogspot.com/2026/06/lsfd-academy-class-426-san-fierro.html', false, '[]'::jsonb),
  ('7301385876733134759', 'pernikahan-mewah-keluarga-petrovich', 'Pernikahan Mewah Keluarga Petrovich Digelar Khidmat di Gereja Jefferson', '2026-04-14T08:56:00.000-07:00', '2026-04-16T04:56:08.599-07:00', 'Arthur Redfields', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEijelpjGHfXOoTKfqD1mokSIESF0WySrKkFx3EV9rhrMxaQHJmPSkWe7Lj9QbiFJQbVx7z2os7vSHs3TVJFg1nzGX2MTzdqBO1eO-gppMt99EfwrEBOG9BqW1ZrbkNcNNqd-k9pS8vHOItd_EF7yVe_MfaTvhN2EvXpcWmK7ZDpX94RY14/s200/In%20Edward%20Snowden%E2%80%99s%20New%20Memoir,%20the%20Disclosures%20This%20Time%20Are%20Personal%20(Published%202019).jpg', 'Senior Staff | HR Trainee', '["Ceremony","Los Santos Event","Social Event","Wedding"]'::jsonb, 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEitBOjbObU7Ak_D8qndeXN8JxE3uedUeSzWnCo-ONLjzuFLvRnyue3aKC92RsdYIn259bQ2R_TnxTj3GOtDyvnTHr2NgsjY1mJX764GimVJLuwD1T-XdjXC9meVXpH2p7M3f8O3-Ues44QAopCA3hVuWIa_lWyI1caOwMAp6hd9rWsCuc_RslRRPQn8V-dj/w640-h366/samp_14_04_2026_20_33_57.jpg', 'Los Santos, FoxSA News — Suasana hangat dan penuh kebahagiaan menyelimuti Gereja Jefferson pada malam hari, saat prosesi pernikahan antara M...', '<div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEitBOjbObU7Ak_D8qndeXN8JxE3uedUeSzWnCo-ONLjzuFLvRnyue3aKC92RsdYIn259bQ2R_TnxTj3GOtDyvnTHr2NgsjY1mJX764GimVJLuwD1T-XdjXC9meVXpH2p7M3f8O3-Ues44QAopCA3hVuWIa_lWyI1caOwMAp6hd9rWsCuc_RslRRPQn8V-dj/s3500/samp_14_04_2026_20_33_57.jpg" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="2000" data-original-width="3500" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEitBOjbObU7Ak_D8qndeXN8JxE3uedUeSzWnCo-ONLjzuFLvRnyue3aKC92RsdYIn259bQ2R_TnxTj3GOtDyvnTHr2NgsjY1mJX764GimVJLuwD1T-XdjXC9meVXpH2p7M3f8O3-Ues44QAopCA3hVuWIa_lWyI1caOwMAp6hd9rWsCuc_RslRRPQn8V-dj/w640-h366/samp_14_04_2026_20_33_57.jpg" /></a></div><div style="text-align: center;"></div><div class="separator" style="clear: both; text-align: center;"><br /></div><div class="separator" style="clear: both; text-align: justify;">Los Santos, FoxSA News — Suasana hangat dan penuh kebahagiaan menyelimuti Gereja Jefferson pada malam hari, saat prosesi pernikahan antara Moses Petrovich dan Alexandra Zevanya resmi digelar di hadapan para tamu undangan.</div><div class="separator" style="clear: both; text-align: justify;"><br /></div><div class="separator" style="clear: both; text-align: justify;">Acara dimulai dengan sambutan dari pembawa acara yang meminta seluruh hadirin untuk menjaga ketenangan demi menghormati kesakralan prosesi. Kedua mempelai kemudian berjalan memasuki altar, disambut tepuk tangan meriah dari para tamu yang hadir.</div><div class="separator" style="clear: both; text-align: justify;"><br /></div><div class="separator" style="clear: both; text-align: justify;">Dalam prosesi tersebut, Moses Petrovich menyampaikan janji setianya kepada Alexandra Zevanya, berkomitmen untuk menjadi pelindung dan pendamping hidup di tengah kerasnya kehidupan Kota Los Santos. Momen semakin menjadi sorotan ketika pihak mempelai pria menunjukkan keseriusannya dengan menyerahkan mahar berupa uang tunai sebesar <b>$100.000</b>, yang dipamerkan secara langsung di altar.</div><div><br /></div><div style="text-align: justify;">Setelah pertukaran janji dan penyematan cincin berlian, pembawa acara secara resmi menyatakan keduanya sebagai pasangan suami istri yang sah. Sorak sorai dan ucapan selamat pun langsung menggema dari seluruh penjuru gereja.</div><div class="separator" style="clear: both; text-align: center;"><br /></div><div style="text-align: justify;">Sebagai penutup, kedua mempelai berbagi momen romantis dengan kecupan hangat yang disambut antusias oleh para tamu. Acara kemudian dilanjutkan dengan sesi foto bersama dan pemberian ucapan selamat dari para undangan.</div><div style="text-align: justify;"><br /></div><div style="text-align: justify;">Pernikahan ini tidak hanya menjadi simbol penyatuan dua insan, tetapi juga menunjukkan kuatnya ikatan dan kehormatan keluarga Petrovich di Kota Los Santos.</div>', 'https://foxsanews.blogspot.com/2026/04/pernikahan-mewah-keluarga-petrovich.html', false, '[]'::jsonb),
  ('2500731608428057736', 'kronologi-penangkapan-dua-perampok', 'Kronologi Penangkapan Dua Perampok Bersenjata Di Kawasan East Los Santos Kamis Sore', '2026-04-10T02:36:00.000-07:00', '2026-04-15T23:29:39.343-07:00', 'Jesus Conway', 'https://4.bp.blogspot.com/-uCjYgVFIh70/VuOLn-mL7PI/AAAAAAAADUs/Kcu9wJbv790hIo83rI_s7lLW3zkLY01EA/s100/avatar.png', 'FoxSA News Crime & Law Enforcement Correspondent', '["Crime","Police","Police Chase"]'::jsonb, 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjj9m08idn1xpHHr-LvOENmqoaHUydnKOCG10TwOpOoNYlOT8TFOqTUZ9qYGZnF7kRzx3is2DeHJOT5iaF4UTvbEbDRfrsLSaxD-da6-bqIstZ26qByptfhzIpdVU2dOGbbEn7zh2Os3MsDRZo2RGcE7L40dYgV9BvcBuoLq_2eJppMXKl7Mq2kyLEKd7W3/w640-h444/Samp.jpg', 'Los Santos, Foxsa News – Suasana tenang di pinggiran kota Red County berubah mencekam pada sore hari pada tanggal 9 April 2026. Pihak kepoli...', '<p></p><div style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjj9m08idn1xpHHr-LvOENmqoaHUydnKOCG10TwOpOoNYlOT8TFOqTUZ9qYGZnF7kRzx3is2DeHJOT5iaF4UTvbEbDRfrsLSaxD-da6-bqIstZ26qByptfhzIpdVU2dOGbbEn7zh2Os3MsDRZo2RGcE7L40dYgV9BvcBuoLq_2eJppMXKl7Mq2kyLEKd7W3/s2048/Samp.jpg" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="1419" data-original-width="2048" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjj9m08idn1xpHHr-LvOENmqoaHUydnKOCG10TwOpOoNYlOT8TFOqTUZ9qYGZnF7kRzx3is2DeHJOT5iaF4UTvbEbDRfrsLSaxD-da6-bqIstZ26qByptfhzIpdVU2dOGbbEn7zh2Os3MsDRZo2RGcE7L40dYgV9BvcBuoLq_2eJppMXKl7Mq2kyLEKd7W3/w640-h444/Samp.jpg" /></a></div><div style="clear: both; text-align: justify;"><br /></div><div class="separator" style="clear: both; text-align: justify;"><div class="separator" style="clear: both;"><b>Los Santos, Foxsa News</b> – Suasana tenang di pinggiran kota <i>Red County</i> berubah mencekam pada sore hari pada tanggal 9 April 2026. Pihak kepolisian terlibat aksi pengejaran sengit dan baku tembak dengan dua pelaku perampokan bersenjata yang mencoba memangsa warga sipil.</div><div class="separator" style="clear: both;"><br /></div><h2 style="clear: both;">Kronologi Kejadian</h2><div><div>Aksi bermula ketika dua pelaku mencoba melakukan penodongan terhadap seorang warga yang melintas. Beruntung, patroli kepolisian yang berada di sekitar lokasi langsung merespons laporan warga. Alih-alih menyerah, para pelaku justru memacu kendaraan mereka dan memicu aksi kejar-kejaran yang berlangsung selama kurang lebih 30 menit menyusuri kota dan berakhir di daerah East Los Santos.</div></div><div><br /></div><h2>Identitas Pelaku dan Persenjataan</h2><div><div>Setelah pengejaran yang melelahkan, kedua pelaku berinisial DC dan AN terpojok. Pihak kepolisian mengungkapkan bahwa kedua tersangka dibekali senjata api berbahaya.</div><div><blockquote>"Mereka menggunakan senjata berupa Shotgun dan Handgun berupa Silenced Pistol" ujar Officer Cole Harrington.</blockquote></div></div><div><br /></div><div><h2>Baku Tembak dan Penangkapan</h2></div><div><div>Puncak ketegangan terjadi saat kedua pelaku melepaskan tembakan ke arah petugas. Baku tembak pun tak terhindarkan di area East Los Santos. Dalam upaya pelariannya, salah satu pelaku mencoba menerobos masuk ke dalam interior sebuah rumah warga untuk dijadikan tempat persembunyian.</div></div><div><br /></div></div><div class="separator" style="clear: both; text-align: center;"><img border="0" data-original-height="2147" data-original-width="3264" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEga-RUTqs3cY3I09dQ22Dvj2vcU0Oq2dN1Yv8bsvetubZ0l6Em6tsuYuo7JRBLxCVkRZ6K7yoq5Xb35nSuXdti1FZB97EjU-05yF45-GDxuBcohtzPHE4-nZbALMeXn3SWWivsp5J2kESNeM9nuQSonmpdnAxyC24CrFKj-u6XSXlgycKd2LWvPJfdLgotU/w640-h420/samp2.jpg" /></div><div class="separator" style="clear: both; text-align: justify;"><span style="font-family: inherit;"><br /></span></div><div class="separator" style="clear: both; text-align: justify;"><span style="font-family: inherit;">Namun, kesigapan anggota kepolisian di lapangan membuahkan hasil. Petugas terpaksa melepaskan tembakan terukur untuk melumpuhkan pelaku yang mencoba masuk ke rumah tersebut guna menghindari jatuhnya korban dari pihak warga sipil.</span></div><div class="separator" style="clear: both; text-align: justify;"><span style="margin-left: 1em; margin-right: 1em;"><div class="separator" style="clear: both; font-family: inherit;"><br /></div><h2 style="clear: both;">Hasil Akhir</h2><div><div>Saat ini, kedua pelaku, DC dan AN, telah berhasil diamankan dalam kondisi terluka dan langsung mendapatkan perawatan medis sebelum menjalani proses hukum lebih lanjut. Seluruh barang bukti berupa satu unit Shotgun dan satu Silenced Pistol telah disita oleh pihak kepolisian.</div></div><div><br /></div><div>Kondisi di daerah Red County dan East Los Santos kini telah kembali kondusif, namun warga tetap dihimbau untuk waspada saat sedang beraktivitas.</div></span></div>', 'https://foxsanews.blogspot.com/2026/04/kronologi-penangkapan-dua-perampok.html', false, '[]'::jsonb),
  ('5158938498669235335', 'polisi-lakukan-pengejaran-di-los-santos', 'Polisi Lakukan Pengejaran di Los Santos, Dua Pelaku Berhasil Diamankan', '2026-04-07T22:33:00.000-07:00', '2026-04-07T22:33:12.855-07:00', 'Arthur Redfields', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEijelpjGHfXOoTKfqD1mokSIESF0WySrKkFx3EV9rhrMxaQHJmPSkWe7Lj9QbiFJQbVx7z2os7vSHs3TVJFg1nzGX2MTzdqBO1eO-gppMt99EfwrEBOG9BqW1ZrbkNcNNqd-k9pS8vHOItd_EF7yVe_MfaTvhN2EvXpcWmK7ZDpX94RY14/s200/In%20Edward%20Snowden%E2%80%99s%20New%20Memoir,%20the%20Disclosures%20This%20Time%20Are%20Personal%20(Published%202019).jpg', 'Senior Staff | HR Trainee', '["Crime","Los Santos","Police","Police Chase"]'::jsonb, 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhWA0JJuZuGXPnm7g2-peK2EoRp8Cb_C3-29NO9WpjUAYsdNgW7ynoEVezq5Vifg_lpBcJfnM5jjPfde1UvjmGPqseX_KSW5LZHOh5vQ_kSJL6hJT2W4Vo60IFL74KyrNtXt0xxKciPgbZvHturEXE7sZ93UUTbB0YFBWRWDJRuAkF0ecGaixe0SZaLKhs0/w640-h334/LSPD.jpg', 'Los Santos, FoxSA News — Pengejaran antara pihak kepolisian dan dua warga terjadi pada Selasa malam, 7 April 2026. Insiden tersebut melibatk...', '<div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhWA0JJuZuGXPnm7g2-peK2EoRp8Cb_C3-29NO9WpjUAYsdNgW7ynoEVezq5Vifg_lpBcJfnM5jjPfde1UvjmGPqseX_KSW5LZHOh5vQ_kSJL6hJT2W4Vo60IFL74KyrNtXt0xxKciPgbZvHturEXE7sZ93UUTbB0YFBWRWDJRuAkF0ecGaixe0SZaLKhs0/s3840/LSPD.jpg" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="2000" data-original-width="3840" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhWA0JJuZuGXPnm7g2-peK2EoRp8Cb_C3-29NO9WpjUAYsdNgW7ynoEVezq5Vifg_lpBcJfnM5jjPfde1UvjmGPqseX_KSW5LZHOh5vQ_kSJL6hJT2W4Vo60IFL74KyrNtXt0xxKciPgbZvHturEXE7sZ93UUTbB0YFBWRWDJRuAkF0ecGaixe0SZaLKhs0/w640-h334/LSPD.jpg" /></a></div><div class="separator" style="clear: both; text-align: center;"><br /></div><div class="separator" style="clear: both; text-align: justify;"><b>Los Santos, FoxSA News</b> — Pengejaran antara pihak kepolisian dan dua warga terjadi pada Selasa malam, 7 April 2026. Insiden tersebut melibatkan dua individu berinisial SS dan MJ yang diduga berkendara secara ugal-ugalan hingga memicu aksi kejar-kejaran dengan aparat.</div><div><br /></div><div style="text-align: justify;">Berdasarkan keterangan petugas di lokasi, pengejaran bermula saat pihak kepolisian melihat sebuah kendaraan Voodoo berwarna biru melaju secara ugal-ugalan di area Vinewood. Petugas kemudian mencoba melakukan <i>traffic stop</i> dengan memberikan perintah untuk menepi melalui pengeras suara.</div><div style="text-align: justify;"><br /></div><div style="text-align: justify;">Namun, kedua pelaku tidak mengindahkan perintah tersebut dan justru meningkatkan kecepatan kendaraan mereka, sehingga pengejaran pun berlangsung cukup lama.</div><div style="text-align: justify;"><br /></div><div style="text-align: justify;"><br /></div><h2 style="text-align: justify;">Kronologi Pengejaran</h2><div style="text-align: justify;">Dalam wawancara bersama reporter FoxSA News, Officer Nicholas Woulfe yang bertindak sebagai Incident Commander menjelaskan bahwa pengejaran berlangsung sekitar 30 menit hingga satu jam.</div><div style="text-align: justify;"><blockquote>“Kami melihat mereka berkendara secara ugal-ugalan di Vinewood, lalu mencoba melakukan traffic stop. Namun mereka tidak menepi dan malah menambah kecepatan,” ujar Officer Woulfe.</blockquote><div><br /></div><div>Pengejaran yang dimulai dari Vinewood tersebut akhirnya berakhir di wilayah Willowfield, tepatnya di sekitar Chluckin Bell, setelah kedua pelaku memasuki sebuah restoran untuk menghindari aparat.</div><div><br /></div><div>Berdasarkan pantauan di lokasi dan keterangan tambahan dari petugas, situasi saat itu masih dalam penanganan tim SWAT yang langsung merespons kejadian tersebut. Area sekitar sempat dibatasi demi kepentingan pengamanan, sementara salah satu pelaku berhasil diamankan dan pelaku lainnya sempat melarikan diri sebelum akhirnya situasi dapat dikendalikan.</div><div><br /></div><div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgJxFLfn1ODiiswueR-Qv23X2fPnSDGOWYZMl8KcCQm2zPdyYcJMrclpj4krcPBAquVpCqYQ4JFpvVzYAtIiYsCd51qy5WvZUdnSCxI-807wWxMoJNBzu_G6rFVQFxvt9XffYzeYu1tW7jisLrDiTLRgjwlIzlFm6seys1wi7hwu4WGdRwRjkI0sLHMDU1m/s3840/LSPD-2.jpg" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="2000" data-original-width="3840" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgJxFLfn1ODiiswueR-Qv23X2fPnSDGOWYZMl8KcCQm2zPdyYcJMrclpj4krcPBAquVpCqYQ4JFpvVzYAtIiYsCd51qy5WvZUdnSCxI-807wWxMoJNBzu_G6rFVQFxvt9XffYzeYu1tW7jisLrDiTLRgjwlIzlFm6seys1wi7hwu4WGdRwRjkI0sLHMDU1m/w640-h334/LSPD-2.jpg" /></a></div><div><br /></div><h2>Tidak Ditemukan Senjata Api</h2><div><div>Dari hasil pemeriksaan awal, kedua pelaku diketahui hanya membawa senjata tajam berupa pisau dan tidak ditemukan adanya senjata api maupun barang ilegal lainnya.</div><div><br /></div><div>Identitas keduanya diketahui sebagai Saul Salamanca dan Meenwyln Jeremiiah, yang disingkat sebagai SS dan MJ berdasarkan kartu identitas yang ditemukan.</div></div><div><br /></div><div><br /></div><h2>Pesan dari Kepolisian</h2><div>Dalam kesempatan tersebut, Officer Woulfe juga menyampaikan pesan kepada warga agar tetap waspada terhadap potensi tindak kriminal di kota.</div><div><blockquote>“Yang terpenting adalah menjaga kesehatan, selalu waspada, dan tidak takut untuk menghubungi 911 jika membutuhkan bantuan. Kami pasti akan membantu,” tambahnya.</blockquote><div><br /></div><div>Pihak kepolisian juga mengingatkan masyarakat untuk tetap berhati-hati dalam beraktivitas serta bekerja sama dengan aparat demi menjaga keamanan di wilayah Los Santos.&nbsp;</div></div></div>', 'https://foxsanews.blogspot.com/2026/04/polisi-lakukan-pengejaran-di-los-santos.html', false, '[]'::jsonb),
  ('7397635371354551208', 'hasil-balapan-pekan-ke-2-san-andreas', 'Hasil Balapan Pekan ke-2 San Andreas Motorsport Championship', '2026-04-07T06:09:00.000-07:00', '2026-04-07T09:12:22.523-07:00', 'Jeremiah Howell', 'https://4.bp.blogspot.com/-uCjYgVFIh70/VuOLn-mL7PI/AAAAAAAADUs/Kcu9wJbv790hIo83rI_s7lLW3zkLY01EA/s100/avatar.png', 'Manager (Event) | Motorsport Analyst', '["Motorsport","San Andreas Motorsport Championship"]'::jsonb, 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgATnYeTPq92s7Wy77YgyfxLiCkWnmdjyeqsj3tKmk5Tp3dnGMFYs6vJXiUeQ_X_hdpf8ig8EHXzVLcOeUqpqdmT1zPVO2r-t17wFTFlx8m5AObK5B4467LKlBbv3BYp0fiFqg_jg4JSeXb3eZdMnPO-67w9PUOLE8JbjzXqXp4PXQO-dsU3dBvdsATXAU/w640-h362/sa-mp-091.png', 'Las Venturas, FoxSA News - Balapan pekan kedua San Andreas Motorsport Championship di Tierra Robada kembali memperlihatkan satu hal yang men...', '<div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgATnYeTPq92s7Wy77YgyfxLiCkWnmdjyeqsj3tKmk5Tp3dnGMFYs6vJXiUeQ_X_hdpf8ig8EHXzVLcOeUqpqdmT1zPVO2r-t17wFTFlx8m5AObK5B4467LKlBbv3BYp0fiFqg_jg4JSeXb3eZdMnPO-67w9PUOLE8JbjzXqXp4PXQO-dsU3dBvdsATXAU/s1920/sa-mp-091.png" style="margin-left: 1em; margin-right: 1em; text-align: center;"><img border="0" data-original-height="1080" data-original-width="1920" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgATnYeTPq92s7Wy77YgyfxLiCkWnmdjyeqsj3tKmk5Tp3dnGMFYs6vJXiUeQ_X_hdpf8ig8EHXzVLcOeUqpqdmT1zPVO2r-t17wFTFlx8m5AObK5B4467LKlBbv3BYp0fiFqg_jg4JSeXb3eZdMnPO-67w9PUOLE8JbjzXqXp4PXQO-dsU3dBvdsATXAU/w640-h362/sa-mp-091.png" /></a></div><div style="text-align: left;"></div><div class="separator" style="clear: both; text-align: center;"><br /></div><div class="separator" style="clear: both; text-align: justify;"><b>Las Venturas, FoxSA News - </b>Balapan pekan kedua San Andreas Motorsport Championship di Tierra Robada kembali memperlihatkan satu hal yang menjadi kenyataan di paddock. <i>Dominasi <b>Akio Asakura </b>masih belum bisa dihentikan.</i></div><div class="separator" style="clear: both; text-align: justify;"><i><br /></i></div><div class="separator" style="clear: both; text-align: justify;">Pada saat sesi kualifikasi yang di lakukan pada hari Jum''at kemarin Akio Asakura menjadi yang tercepat, di balapan kali ini dirinya kembali menjadi yang tercepat dan finish di posisi pertama setelah pada pekan pembuka Akio memenangkan balapan yang di gelar di Center San Fierro, ini menjadi kemenangan kedua Akio musim ini. Disusul Chiyoko Yamamura yang berhasil finish di posisi kedua setelah naik&nbsp; satu peringkat dari peringkat ketiga dan disusul Zeen Nagata yang harus rela finish di posisi ketiga setelah turun satu peringkat, dan juga di balapan kali ini Ryota Shima yang merupakan rekan satu tim Akio Asakura di <i>SandRidge Bodywork Racing Team</i> keluar sebagai <i>Driver of the day </i>setelah berhasil menyalip 9 pembalap dan finish di posisi ke-8.</div><div class="separator" style="clear: both; text-align: justify;"><br /></div><span><a name=''more''></a></span><div class="separator" style="clear: both; text-align: justify;"><br /></div><div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgXpWE3U0Te0eU01r2cR6v4vciC0cZke9q4wzggQ_btteTNgkCCHmssJAb9JSO93J7Ymr8djNM-R8oECfT_ZNWrddoyWB29eELAlWUTx4oZO-4-Xg1cByt6qh_eQfL5Wt1qpEDvqEoxyHoUn2cxV925wvycTs0p8lA60LYzhYPhi9PxeGOCnDOfBD7jil4/s1920/sa-mp-016-1.png" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="1080" data-original-width="1920" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgXpWE3U0Te0eU01r2cR6v4vciC0cZke9q4wzggQ_btteTNgkCCHmssJAb9JSO93J7Ymr8djNM-R8oECfT_ZNWrddoyWB29eELAlWUTx4oZO-4-Xg1cByt6qh_eQfL5Wt1qpEDvqEoxyHoUn2cxV925wvycTs0p8lA60LYzhYPhi9PxeGOCnDOfBD7jil4/w640-h361/sa-mp-016-1.png" /></a></div><div class="separator" style="clear: both; text-align: center;"><br /></div><h2 style="clear: both; text-align: justify;">Persaingan Mental dan Keahlian</h2><div style="text-align: justify;">Di balapan ini banyak terjadi pertarungan-pertarungan yang sangat seru dan menegangkan, diantaranya Chiyoki dan Zeen yang sangat sengit memperebutkan posisi kedua. Park Yohan, Hans Schumacher dan Orlando Draco memperebutkan posisi keempat, pertarungan ini berjalan cukup lama sampai akhirnya Hans Schumacher yang berhasil finish di posisi keempat disusul Orlando Draco kelima dan Park Yoha di posisi keenam.</div><div style="text-align: justify;"><br /></div><span><!--more--></span><h2 style="text-align: justify;">Strategi Tim dan Hasil Latihan Yang Membuahkan Hasil Manis</h2><div style="text-align: justify;"><span>Dalam sesi wawancara bersama reporter Jeremiah Howell. Akio Asakura mengatakan bahwa hasil yang ia dapat, buah dari kerja keras tim dan latihan dirinya.</span></div><div><blockquote style="text-align: justify;"><span>"Seperti biasa. mengumpulkan data. kemudian mencoba mempraktekannya "</span><span> merujuk pada strategi tim untuk balapan kali ini</span></blockquote><p></p><div style="text-align: justify;">Sampai saat ini, perebutan gelar juara masih di pimpin oleh Akio Asakura dengan perolehan 52 poin, di posisi kedua diisi oleh Park Yohan dengan 23 poin dan diposisi ketiga ditempati oleh Chiyoko Yamamura dengan 22 poin.</div><div style="text-align: left;"><div style="text-align: justify;"><br /></div><div style="text-align: justify;">Perebutan gelar juara dunia semakin sangat sengit dan seru, terlebih lagi masih menyisakan tiga balapan di musim ini.</div></div><div style="text-align: left;"><div style="text-align: justify;"><br /></div><div style="text-align: justify;">Nantikan setiap gelaran San Andreas Motorsport Championsip untuk menyaksikan aksi pembalap-pembalap di sirkuit untuk satu gelar yaitu menjadi juara dunia.</div></div></div><p></p>', 'https://foxsanews.blogspot.com/2026/04/hasil-balapan-pekan-ke-2-san-andreas.html', false, '[{"id":"4712648963678093116","author":"Chiyoko Yamamura","avatar":"https://4.bp.blogspot.com/-uCjYgVFIh70/VuOLn-mL7PI/AAAAAAAADUs/Kcu9wJbv790hIo83rI_s7lLW3zkLY01EA/s100/avatar.png","date":"2026-04-07T07:08:28.402-07:00","body":"👍"}]'::jsonb),
  ('4450397324690086093', 'las-venturas-foxsa-news-dominasi', 'Dominasi pembalap Jepang Akio Asakura di San Andreas Motorsport Championship', '2026-04-04T21:23:28.869-07:00', '2026-04-05T04:19:46.074-07:00', 'Arthur Redfields', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEijelpjGHfXOoTKfqD1mokSIESF0WySrKkFx3EV9rhrMxaQHJmPSkWe7Lj9QbiFJQbVx7z2os7vSHs3TVJFg1nzGX2MTzdqBO1eO-gppMt99EfwrEBOG9BqW1ZrbkNcNNqd-k9pS8vHOItd_EF7yVe_MfaTvhN2EvXpcWmK7ZDpX94RY14/s200/In%20Edward%20Snowden%E2%80%99s%20New%20Memoir,%20the%20Disclosures%20This%20Time%20Are%20Personal%20(Published%202019).jpg', 'Senior Staff | HR Trainee', '["Motorsport","San Andreas Motorsport Championship"]'::jsonb, 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgbRaJihev9UZTN65GAIPKR8YBFq1sii-5brHfhVrFiDMaMKizgkZ6qLN-Z0ONrg6JzX7djB_MA4WHRFeaxauToaQ-8rPpj4eDB3BjKuK7TmZPFJAdC8_PpPbAZZH1lywOTUVM3s07oJ494Zsk4VGVX7WL4p3IQdGqI8uh0CV1Rxdu6puOdrsxXQ23q9gWK/w640-h360/Akio.jpg', 'Las Venturas, FoxSA News — Dominasi pembalap asal Jepang, Akio Asakura, kembali berlanjut dalam ajang San Andreas Motorsport Championship. S...', '<div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgbRaJihev9UZTN65GAIPKR8YBFq1sii-5brHfhVrFiDMaMKizgkZ6qLN-Z0ONrg6JzX7djB_MA4WHRFeaxauToaQ-8rPpj4eDB3BjKuK7TmZPFJAdC8_PpPbAZZH1lywOTUVM3s07oJ494Zsk4VGVX7WL4p3IQdGqI8uh0CV1Rxdu6puOdrsxXQ23q9gWK/s3840/Akio.jpg" style="margin-left: 1em; margin-right: 1em; text-align: center;"><img border="0" data-original-height="2160" data-original-width="3840" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgbRaJihev9UZTN65GAIPKR8YBFq1sii-5brHfhVrFiDMaMKizgkZ6qLN-Z0ONrg6JzX7djB_MA4WHRFeaxauToaQ-8rPpj4eDB3BjKuK7TmZPFJAdC8_PpPbAZZH1lywOTUVM3s07oJ494Zsk4VGVX7WL4p3IQdGqI8uh0CV1Rxdu6puOdrsxXQ23q9gWK/w640-h360/Akio.jpg" /></a></div><div style="text-align: left;"></div><div style="text-align: center;"><br /></div><div style="text-align: justify;"><b>Las Venturas, FoxSA News</b> — Dominasi pembalap asal Jepang, Akio Asakura, kembali berlanjut dalam ajang San Andreas Motorsport Championship. Setelah menjadi pemenang di minggu pertama, Akio kini kembali menjadi yang tercepat di kualifikasi&nbsp; minggu kedua dengan catatan waktu 2:27.832.</div><div style="text-align: left;"><span style="text-align: justify;"><br /></span></div><div><div style="text-align: justify;">Kualifikasi yang berlangsung di wilayah Tierra Robada ini kembali menjadi milik Akio Asakura yang keluar sebagai Pole Position, dominasinya tidak tertandingi di kualifikasi minggu kedua, dimana Akio Asakura menjadi yang tercepat di Q1 dan Q2.</div><div style="text-align: justify;"><br /></div><div style="text-align: justify;"><hr data-end="2460" data-start="2457" /><h3 data-end="2509" data-section-id="1yhy0co" data-start="2462"></h3></div><h4 style="text-align: justify;">Konsistensi Akio Asakura di&nbsp;San Andreas Motorsport Championship</h4><div><div style="text-align: justify;">Dalam wawancara bersama reporter Arthur Redfields, Akio mengonfirmasi bahwa performanya masih stabil sejak kemenangan sebelumnya di minggu pertama San Andreas Motorsport Championship.</div><div><blockquote style="text-align: justify;">“Ya, ini yang kedua kalinya,” ujarnya, merujuk pada dominasinya dalam dua pekan terakhir di event yang sama.</blockquote><div>&nbsp;</div></div><div style="text-align: justify;">Meski kembali memimpin, Akio tetap menunjukkan sikap realistis terhadap persaingan.</div><div><blockquote style="text-align: justify;">“Kalau soal menang dan kalah itu tidak pasti... ada faktor mobil atau kesalahan lain.”</blockquote><div>&nbsp;</div></div><div style="text-align: justify;">Ia juga memberikan pesan kepada para rivalnya:</div><div><blockquote style="text-align: justify;">“Jangan menyerah. Teruslah menginjak pedal gas.”</blockquote><div>&nbsp;</div><hr data-end="2460" data-start="2457" /><h3 data-end="2509" data-section-id="1yhy0co" data-start="2462"></h3><h3 style="text-align: justify;">Zeen Nagata dan Chiyoko Yamamura Mengintai</h3></div></div></div><div class="separator" style="clear: both; text-align: center;"><a href="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjlkPRKMoEv5tKzzmm9IsA3wP9dKO74r0zpxNqYh_Qct3j1Fz0r5HQDKrCdijAvnS_hVZVn0f09PrEIXtCG7A36uCcNemgcjptZXLQ8T_XIhe5t6zXQjj1OcvVtRPmBIIrH2is9aFgtxjyJ460noMJ5XxwxXuR2nlNpVE1a1ZwoNuZ0wlx-EmHiUyISjLzN/s3840/Zeen,%20Chiyoko.png" style="margin-left: 1em; margin-right: 1em;"><img border="0" data-original-height="1750" data-original-width="3840" src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjlkPRKMoEv5tKzzmm9IsA3wP9dKO74r0zpxNqYh_Qct3j1Fz0r5HQDKrCdijAvnS_hVZVn0f09PrEIXtCG7A36uCcNemgcjptZXLQ8T_XIhe5t6zXQjj1OcvVtRPmBIIrH2is9aFgtxjyJ460noMJ5XxwxXuR2nlNpVE1a1ZwoNuZ0wlx-EmHiUyISjLzN/w640-h292/Zeen,%20Chiyoko.png" /></a></div><div class="separator" style="clear: both; text-align: center;"><br /></div><div class="separator" style="clear: both; text-align: justify;"><div class="separator" style="clear: both;">Di posisi kedua, Zeen Nagata mencatat waktu 2:29.070 dan menyoroti peningkatan performa kendaraan sebagai kunci utama.</div><div class="separator" style="clear: both;"><blockquote>“Membuat mobil ini lebih baik dalam aerodinamis dan exit corner.”</blockquote><div>&nbsp;</div></div><div class="separator" style="clear: both;">Sementara itu, Chiyoko Yamamura yang berada di posisi ketiga mengaku belum puas dengan hasil yang diraihnya.</div><div class="separator" style="clear: both;"><blockquote>“Sejujurnya... saya tidak terlalu senang dengan posisi 3.”</blockquote><div>&nbsp;</div></div><div class="separator" style="clear: both;">Ia bahkan merasa memiliki peluang untuk finis lebih tinggi.</div><div class="separator" style="clear: both;"><blockquote>“Andai waktu terakhirku dihitung, maka aku akan mendapatkan posisi 2.”</blockquote><div>&nbsp;</div></div><div class="separator" style="clear: both;">Pembalap dari tim Carvello Untraceable GT ini juga mengingatkan para pembalap lain:</div><div class="separator" style="clear: both;"><blockquote>“Untuk yang akan di-overlap, tolong jangan melakukan blocking dan berikan jalan.”</blockquote><div>&nbsp;</div></div><div class="separator" style="clear: both;">Namun, ia menutup dengan pernyataan penuh percaya diri.</div><div class="separator" style="clear: both;"><blockquote>“Aku ingin memberikan kejutan untuk balapan besok.”</blockquote><div>&nbsp;</div><hr data-end="2460" data-start="2457" /><h3 data-end="2509" data-section-id="1yhy0co" data-start="2462"></h3><h3>Pembuktian para pembalap di balapan malam ini</h3><div><div>Persaingan malam ini akan sangat seru pastinya, dimana saat di interview setelah selesai kualifikasi Zeen dan tim sudah mempersiapkan strategi khusus dan Chiyoko yang akan memberikan kejutan di balapan nanti.</div><div><br /></div><div>Akio yang malam ini akan memulai start di paling depan, namun tekanan dari Zeen dan Chiyoko yang berada di belakangnya tentunya akan menjadi tantangan bagi Akio untuk mempertahankan posisinya.</div><div><br /></div><div>Balapan malam ini akan menjadi pembuktian apakah Akio akan mempertahankan posisinya atau akan ada yang meruntuhkan dominasi Akio di Tierra Robada, Las Venturas.</div></div></div></div>', 'https://foxsanews.blogspot.com/2026/04/las-venturas-foxsa-news-dominasi.html', false, '[]'::jsonb)
ON CONFLICT (id) DO NOTHING;

